import pandas as pd,numpy as np
from scipy.optimize import least_squares
def simulate(p,d):
    Kq,Tq,Kpv,Kw,Tw,Tp=p
    t=d.time_s.values; V=d.voltage_pu.values; th=d.bus_angle_rad.values; Vs=d.voltage_setpoint_pu.values
    P0=d.active_power_pu.values[0]; Q0=d.reactive_power_pu.values[0]; V0=V[0]; th0=th[0]
    n=len(t); h=t[1]-t[0]
    Pm=np.zeros(n); Qm=np.zeros(n); Qs=Q0; z=th0; Ps=P0
    for i in range(n):
        Qm[i]=Qs; Pm[i]=Ps
        Pr=P0+Kpv*(V[i]-V0)-Kw*(th[i]-z)
        Qs+=h*((Q0+Kq*(Vs[i]-V[i])-Qs)/Tq)
        z+=h*((th[i]-z)/Tw); Ps+=h*((Pr-Ps)/Tp)
    return Pm,Qm
